use std::{collections::BTreeMap,fs};
fn load(p:&str)->BTreeMap<Vec<u64>,Vec<String>>{let mut o=BTreeMap::new();for l in fs::read_to_string(p).unwrap().lines().skip(1){let v:Vec<String>=l.split('\t').map(str::to_string).collect();assert_eq!(v.len(),14);let k=v[..6].iter().map(|x|x.parse().unwrap()).collect();assert!(o.insert(k,v).is_none());}assert_eq!(o.len(),128);o}
fn main(){let root="research/hec_residual_span_20261116";let old=load(&format!("{root}/incremental-pencil/CONTROL.tsv"));let new=load(&format!("{root}/stream-pencil/CONTROL.tsv"));let mut range=BTreeMap::<(u64,bool),(f64,f64)>::new();
println!("g\tp\tsm\tcase\tmodulus\told_REDC\tnew_REDC\told_over_new_REDC\told_rows\tnew_rows\told_anchors\tnew_anchors");
for(k,v)in &new {let o=&old[k];assert_eq!(&v[6..9],&o[6..9]);assert_eq!(v[8],"true");assert_eq!(v[6],v[7]);let cs:Vec<u64>=v[13].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(cs.len(),16);assert_eq!(cs[8],2*cs[7]+cs[5]+cs[6]);if k[4]==1{let mut z=k.clone();z[4]=0;assert_eq!(&new[&z][6..],&v[6..]);continue}let oc:Vec<u64>=o[13].split(',').map(|x|x.parse().unwrap()).collect();let r=oc[8] as f64/cs[8] as f64;let e=range.entry((k[0],k[1]==k[5])).or_insert((r,r));e.0=e.0.min(r);e.1=e.1.max(r);println!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:.6}\t{}\t{}\t{}\t{}",k[0],k[1],k[2],k[3],k[5],oc[8],cs[8],r,o[9],v[9],o[10],v[10]);}
for((g,base),(lo,hi))in range{eprintln!("g={g} base_field={base} min_REDC_ratio={lo:.6} max_REDC_ratio={hi:.6}");}eprintln!("records=128 same_targets_and_verified_scalars=true repeats=true REDC_identity=true");}
